function login(){user=null;$('#app').html(`<div class="card"><h2>PLP Enrollment Management System</h2><p class="mu">Pamantasan ng Lungsod ng Pasig. Demo password for every account: demo1234</p><label>Account<select id="ue">${S.users.map(u=>`<option value="${u.email}">${e(u.name)} (${{R:'Registrar',H:'Department Head',S:'Student',P:'Professor'}[u.role]})${u.role=='S'&&stu(u.sid)?' '+e(stu(u.sid).adm)+', year '+stu(u.sid).yl:''}</option>`).join('')}</select></label><label>Password<input id="up" type="password" autocomplete="current-password"></label><div id="le"></div><button class="p" id="lg">Log in</button></div>`)}

function shell(){SM=S.sem;const N={R:['Dashboard','Students','Admission year','Special enrollment','Colleges','Sections','Subjects','Scheduler','Rooms','Import','Audit log','Account'],H:['Special students','Account'],S:['My enrollment','Grades','Account'],P:['Submit grades','Account']}[user.role];
if(user.role=='S'&&stu(user.sid).cls=='Irregular')N.splice(N.indexOf('Account'),0,'Notifications');if(user.mustChange)view='Account';if(!view||!N.includes(view))view=N[0];
$('#app').html(`<header><b>PLP Enrollment</b><span>${e(user.name)} <button id="lo">Log out</button></span></header><nav>${N.map(n=>`<a tabindex="0" data-v="${n}" class="${n==view?'on':''}">${n}</a>`).join('')}</nav><main id="main"></main><footer class="mu" style="text-align:center;padding:16px">Prototype: records are kept in this browser only.</footer>`);
({Dashboard:rDash,Students:rStu,'Admission year':rAdmY,'Special enrollment':rSpec,Subjects:rSub,Scheduler:rSch,Rooms:rSec,Colleges:rCol,Sections:rSecs,Import:rImp,'Audit log':rAud,Account:rAcc,'Special students':rKQ,'My enrollment':rMine,Grades:rGrades,Notifications:rNotif,'Submit grades':rSubmit})[view]()}

// ---------- academic rules (stand-in for the Laravel backend) ----------
function elig(s,c){if(ok(s.rec[c]))return'Already completed';if(s.cls=='Regular'){const f=sub(c).pre.filter(p=>['FAILED','INCOMPLETE'].includes(s.rec[p]));return f.length?'Failed prerequisite '+f.join(', ')+', needs Department Head':''}const m=sub(c).pre.filter(p=>!ok(s.rec[p]));return m.length?'Needs '+m.join(', '):''}
const cap=a=>Math.min(room(a.room).cap,sec(a.sec).cap);
const used=(a,s)=>S.students.filter(x=>x.id!=s.id&&['Proposal sent','Awaiting registrar','Accepted','Finalized'].includes(x.st)&&x.items.includes(a.id)).length;
const clash=(a,b)=>(a.sem||1)==(b.sem||1)&&a.day==b.day&&a.s<b.e&&b.s<a.e;
function vItems(s,ids,dh){const er=[],L=ids.map(i=>S.sched.find(x=>x.id==i));if(!L.length)er.push('Select at least one subject.');
L.forEach(a=>{const r=dh?(ok(s.rec[a.code])&&!regBase(s).includes(a.id)?'Already completed':''):elig(s,a.code);if(r)er.push(a.code+': '+r);else if(dh&&preGap(s,a.code).length)er.push(a.code+': prerequisite not passed ('+preGap(s,a.code).join(', ')+'), not enrolled.');if(used(a,s)>=cap(a))er.push(a.code+' '+a.sec+' is full.');L.forEach(b=>{if(a.id<b.id&&clash(a,b))er.push('Schedule conflict: '+a.code+' and '+b.code)});if(a.id<L.length&&0){}});
if(new Set(L.map(a=>a.code)).size<L.length)er.push('The same subject is selected twice.');if(s.cls=='Regular')S.subjects.filter(x=>x.on&&x.yl==s.yl&&x.sem==S.sem&&subOk(x,s.prog)&&schH(s.sec,x.code)<x.u).forEach(x=>er.push(x.code+' is not fully scheduled for '+s.sec+' ('+schH(s.sec,x.code)+' of '+x.u+' hrs).'));return er}
function vSch(n){const er=[],sb=sub(n.code),rm=room(n.room),pf=prof(n.prof),tt=termOf(n.sem);if(n.sem!=S.sem)er.push('Semester '+n.sem+' is view only. Only the active semester ('+ordN(S.sem)+') can be edited.');if(!(tt.s&&tt.e))er.push('Set the start and end dates of semester '+n.sem+' first. Room assignments follow those dates.');else if(tt.e<todayISO())er.push('Semester '+n.sem+' already ended on '+dfmt(tt.e)+'.');
if(!sb.on)er.push('Subject is inactive.');if(semLocked(n.sem,n.sec))er.push('The schedule of this section for this semester is finalized.');if(sb.yl!=sec(n.sec).yl||sb.sem!=n.sem)er.push(n.code+' is offered in year '+sb.yl+', semester '+sb.sem+' only.');const have=S.sched.filter(x=>x.id!=n.id&&x.sec==n.sec&&x.code==n.code&&(x.sem||1)==n.sem).reduce((t,x)=>t+x.e-x.s,0);if(have+n.e-n.s>sb.u)er.push(n.code+' needs '+sb.u+' hrs per week and '+n.sec+' already has '+have+' scheduled.');if(!sb.days.includes(n.day))er.push(n.code+' may only be held on '+sb.days.join(', ')+'.');
if(rm.rt!=sb.rt)er.push('A '+rm.rt+' room does not fit a '+sb.rt+' subject.');if(!rm.on)er.push('Room '+rm.id+' is unavailable.');
if(S.students.filter(x=>x.sec==n.sec).length>rm.cap)er.push('Room capacity is below the section head count.');
if(pf.st!='Active')er.push(pf.name+' is inactive.');if(!pf.q.includes(n.code))er.push(pf.name+' is not authorized to teach '+n.code+'.');
S.sched.filter(x=>x.id!=n.id&&clash(x,n)).forEach(x=>{if(x.room==n.room)er.push('Room '+n.room+' is taken by '+x.code+' ('+tm(x.s)+'–'+tm(x.e)+').');if(x.prof==n.prof)er.push(pf.name+' already teaches '+x.code+' then.');if(x.sec==n.sec)er.push(n.sec+' already has '+x.code+' then.')});return er}
function wouldCycle(c,pre){const seen=new Set();const go=x=>{if(x==c)return true;if(seen.has(x))return false;seen.add(x);return(sub(x)?sub(x).pre:[]).some(go)};return pre.some(go)}

