function finInfo(){const m=S.sem,ids=S.sched.filter(a=>(a.sem||1)==m),pend=S.students.filter(s=>s.items.length&&s.items.some(i=>{const a=S.sched.find(x=>x.id==i);return a&&!(s.gr&&s.gr[a.code])})).length,enr=S.students.filter(s=>s.st=='Finalized').length;return{m,classes:ids.length,pend,enr}}
