function rSub(){$('#main').html(`<h2>Subjects and prerequisites</h2><p class="mu">Select a row to edit that subject.</p><input id="q" placeholder="Search subjects" data-t="#main .sbg">`+sbGroups(S.subjects.map(x=>[x.code,e(x.name),'Y'+x.yl+' S'+x.sem,x.u,x.rt,x.days.join(' '),x.pre.join(', ')||'None',bd(x.on?'Active':'Inactive'),`<button class="pre" data-c="${x.code}">Edit prerequisites</button> <button class="tog" data-c="${x.code}">${x.on?'Deactivate':'Activate'}</button>`]),'sb')+`<h3>${ed?'Edit '+ed:'Add subject'}</h3><div id="se"></div><p><select id="sk">${scopeOpts()}</select> <span class="mu">Where this subject belongs</span></p><p><input id="nc" placeholder="Code, e.g. IT104" value="${e(X().code||'')}" ${ed?'readonly':''}> <input id="nn" placeholder="Name" value="${e(X().name||'')}"> <input id="nu" type="number" min="1" max="6" value="${X().u||3}" style="width:70px"> <select id="sy2">${[1,2,3,4].map(y=>`<option value="${y}" ${(X().yl||1)==y?'selected':''}>Year ${y}</option>`).join('')}</select> <select id="sm">${[1,2].map(m=>`<option value="${m}" ${(X().sem||1)==m?'selected':''}>Sem ${m}</option>`).join('')}</select> <select id="nt">${['Room','Lab','Gym'].map(o=>`<option ${X().rt==o?'selected':''}>${o}</option>`).join('')}</select></p><p>${DAYS.map(d=>`<label><input type="checkbox" class="nd" value="${d}" ${(!ed||X().days.includes(d))?'checked':''}> ${d}</label> `).join('')}</p><p><select id="np" multiple size="4">${S.subjects.filter(x=>x.code!=ed&&term(x)<term(ed?X():{yl:1,sem:1})).map(x=>`<option ${(X().pre||[]).includes(x.code)?'selected':''}>${x.code}</option>`).join('')}</select> <span class="mu">Hold Ctrl or Cmd to pick several prerequisites.</span></p><button class="p" id="ns">${ed?'Update subject':'Save subject'}</button>${ed?' <button id="ned">Cancel edit</button>':''}`)}
