// ---------- proposal builder (registrar and department head) ----------
function builder(id,role){if(role=='H'){dhBuild(id);return}const s=stu(id);B={id,role};
const cr=role=='H'&&s.cls!='Irregular'?`<h3>Credit subjects</h3><p>${S.subjects.map(x=>`<label><input type="checkbox" class="cr" value="${x.code}" ${s.rec[x.code]=='CREDITED'?'checked':''} ${s.rec[x.code]=='PASSED'?'disabled':''}> ${x.code}</label> `).join('')} <button id="csv">Save credits</button></p>`:'';
const reqs=s.req.length?`<p>Requested back subjects: <b>${s.req.join(', ')}</b></p>${role=='H'?'<p class="mu">Join the classes of lower-year sections that take these subjects.</p>':''}`:'';
const rows=S.sched.filter(a=>(a.sem||1)==S.sem&&(B.role=='H'?(!s.req.length||s.req.includes(a.code)):(a.sec==s.sec||s.items.includes(a.id)))).map(a=>{const gap=B.role=='R'&&!s.items.includes(a.id)&&!ok(s.rec[a.code])?preGap(s,a.code):[],r=(gap.length?'':(s.stage=='dh'&&s.items.includes(a.id)?'':elig(s,a.code)))||(B.role=='R'&&s.cls!='Regular'&&!s.items.includes(a.id)?cf(s,a):'');return[`<input type="checkbox" class="pk" value="${a.id}" ${(s.cls=='Regular'?a.sec==s.sec:s.items.includes(a.id))&&!r?'checked':''} ${r||s.cls=='Regular'||(B.role=='R'&&s.stage=='dh'&&s.items.includes(a.id))?'disabled':''}>`,a.code+' '+e(sub(a.code).name),a.sec,a.day+' '+tm(a.s)+'–'+tm(a.e),'Room '+a.room,e(prof(a.prof).name),used(a,s)+'/'+cap(a),r?`<span class="mu">${r}</span>`:(gap.length?'<span class="b y">Prerequisite not passed ('+gap.join(', ')+'): not enrolled, goes to the student\'s waiting list</span>':'Eligible')]});
$('#main').html(`<h2>${role=='H'?'Evaluate':'Build proposal for'} ${e(s.name)} <small>${s.cls}, ${s.prog}, year ${s.yl}</small></h2><p>Completed: ${Object.entries(s.rec).map(([k,v])=>k+' '+bd(v)).join(' ')||'No records'}</p>${reqs}${cr}${s.cls=='Regular'?'<p class="mu">Regular students are enrolled in every class scheduled for their section.</p>':''}`+tbl(['','Subject','Section','When','Room','Professor','Seats','Eligibility'],rows)+`<div id="be"></div><button class="p" id="send">${role=='H'?'Accept re-enrollment and forward to Registrar':'Send proposal to student'}</button> ${role=='H'?'<button class="d" id="rej">Reject</button> ':''}<button id="bk">Back</button>`)}
function rQueue(){$('#main').html('<h2>Special cases</h2>'+tbl(['ID','Name','Class','Requested','Status',''],S.students.filter(s=>s.st=='Awaiting evaluation'||s.st=='Revision requested'&&s.stage=='dh').map(s=>[s.id,e(s.name),s.cls,s.req.join(', ')||'—',bd(s.st),`<button class="p bld" data-id="${s.id}">Evaluate</button>`])))}

// ---------- student ----------
function rMine(){const s=stu(user.sid);let b='';const cur=s.items.map(i=>S.sched.find(x=>x.id==i));
const t=cur.length?tbl(['Subject','Units','Section','Professor','Room','Day','Time'],cur.map(a=>[a.code+' '+e(sub(a.code).name),sub(a.code).u,a.sec,e(prof(a.prof).name),a.room,a.day,tm(a.s)+'–'+tm(a.e)]))+`<p>Total units: <b>${cur.reduce((n,a)=>n+sub(a.code).u,0)}</b></p>`:'';
if(s.st=='Proposal sent')b=t+(s.stage=='dh'?`<p class="mu">The Registrar made your COR and the Department Head added your requested subjects${s.req.length?' ('+s.req.map(e).join(', ')+')':''}. Your approval completes the enrollment.</p>`:'')+`<p><label>Remarks, required if you decline<br><input id="sr" size="50"></label></p><div id="sre"></div><button class="p" id="acc">Accept enrollment</button> <button class="d" id="dec">Decline and request revision</button>`;
else if(s.st=='Finalized')b=t+`<button class="p cor-b" data-id="${s.id}">View and print COR</button>`;
else if(s.cls=='Irregular'&&s.st=='New'){const bk=S.subjects.filter(x=>s.rec[x.code]=='FAILED'||(!s.rec[x.code]&&0));b=`<h3>Back subjects</h3><p>${bk.map(x=>`<label><input type="checkbox" class="bk" value="${x.code}" checked> ${x.code} ${e(x.name)}</label><br>`).join('')||'None found.'}</p><button class="p" id="rq">Request these subjects</button>`}
else b=`<p>${{'New':'Waiting for the Registrar to send your proposal.','Awaiting evaluation':'Waiting for the Department Head to evaluate your records.','Awaiting registrar':'The Registrar is adding the remaining curriculum subjects.','Revision requested':'Your revision request is with the evaluator.','Accepted':'Accepted. Waiting for Registrar finalization.','Rejected':'Your request was not approved. See notifications.'}[s.st]}</p>`+t;
$('#main').html(`<h2>${e(s.name)} <small>${s.prog}, year ${s.yl}, ${s.cls}, ${bd(s.st)}</small></h2>${b}${waitBox(s)}${sameTerm(s)&&s.cls=='Irregular'?'<p class="mu">You are enrolled for this semester. You can request new back subjects when the next semester opens and you will get a new COR.</p>':reqBlock(s)}${s.cors&&s.cors.length&&s.st!='Finalized'?`<h3>Previous CORs</h3><p>${s.cors.map((x,j)=>`<button class="cor-b" data-id="${s.id}" data-i="${j}">COR ${j+1}: ${x.sem==1?'1st':'2nd'} sem</button>`).join(' ')}</p>`:''}<h3>Notifications</h3>${s.notes.map(n=>'<p>'+e(n)+'</p>').join('')}`)}
function showCOR(id,k){const s=stu(id),all=s.cors||(s.cor?[s.cor]:[]),i=k==null?all.length-1:k,c=all[i]||s.cor,L=c.rows||(c.items||s.items).map(x=>S.sched.find(y=>y.id==x)).filter(Boolean).map(snap),cm=c.sem||S.sem,ct=c.t||termOf(cm);
$('#main').html(`<p class="np"><button class="p" onclick="window.print()">Print or save as PDF</button> <button id="bk2">Back</button> ${all.length>1?all.map((x,j)=>`<button class="cor-b ${j==i?'p':''}" data-id="${s.id}" data-i="${j}">COR ${j+1}: ${x.sem==1?'1st':'2nd'} sem${x.kind=='Back subjects'?' (back subjects)':''}</button>`).join(' '):''}</p><div class="cor"><h2 style="text-align:center">Pamantasan ng Lungsod ng Pasig<br>Certificate of Registration</h2><p>Student ID: <b>${s.id}</b> &nbsp; Name: <b>${e(s.name)}</b> &nbsp; Email: ${e(s.email)}<br>Program: ${s.prog} &nbsp; Year: ${c.yl||s.yl} &nbsp; Section: ${s.sec||'-'} &nbsp; Term: AY ${c.ay||2026}-${(c.ay||2026)+1}, ${cm==1?'1st':'2nd'} Semester (${dfmt(ct.s)} to ${dfmt(ct.e)})<br>Enrolled: ${c.date} &nbsp; Status: Officially enrolled &nbsp; Type: ${c.kind||'Enrollment'} &nbsp; COR no.: ${c.v}</p>`+tbl(['Code','Subject','Units','Professor','Room','Day','Time'],L.map(a=>[a.code,e(a.name),a.u,e(a.prof),a.room,a.day,tm(a.s)+'–'+tm(a.e)]))+`<p>Total enrolled units: <b>${L.reduce((n,a)=>n+a.u,0)}</b></p></div>`)}

