$(document).on('click','.rm',function(){const id=+$(this).data('id'),a=S.sched.find(x=>x.id==id);if(!a)return;if(secFinal(a.sec)){alert('This section is finalized, so its schedule is view only.');return}if(S.students.some(x=>x.st=='Finalized'&&x.items.includes(id))){alert('Finalized students are enrolled in this class, so it cannot be removed.');return}
S.sched=S.sched.filter(x=>x.id!=id);S.students.forEach(s=>{if(s.st!='Finalized'&&s.items.includes(id)){s.items=s.items.filter(i=>i!=id);if(['Proposal sent','Accepted'].includes(s.st)){s.st=s.cls=='Regular'?'New':'Revision requested';note(s,'A class in your proposal was removed. Waiting for an updated proposal.')}}});syncSec(a.sec);log('Removed class '+a.code+' '+a.sec);save();rSch()});
$(document).on('click','#ib',async()=>{let d,er=[],c=0,u=0,j=0;try{d=JSON.parse($('#ij').val())}catch(x){$('#ie').html(errs(['Invalid JSON: '+x.message]));return}
for(const r of d.students||[]){const m=['admission_id','first_name','last_name','email','program_code'].filter(k=>!r[k]);if(m.length||!/ADMITTED|APPROVED/.test(r.admission_status||'')){j++;er.push((r.admission_id||'record')+': '+(m.length?'missing '+m.join(', '):'not admitted'));continue}
const nm=r.first_name+' '+r.last_name,ex=S.students.find(x=>x.adm==r.admission_id);if(ex){ex.name=nm;ex.email=r.email;u++;continue}
if(S.users.some(x=>x.email==r.email)){j++;er.push(r.admission_id+': email already used');continue}
const id='S'+S.nid++;S.students.push({id,adm:r.admission_id,name:nm,email:r.email,prog:r.program_code,yl:r.year_level||1,cls:'Regular',sec:'',rec:{},st:'New',stage:'',items:[],hist:[],req:[],notes:['Your account is ready. Set a new password on first login.'],cor:null});
S.users.push({email:r.email,name:nm,role:'S',sid:id,pw:await h(r.temporary_password||crypto.randomUUID()),mustChange:true});c++}
autoAll();S.imports.unshift({t:new Date().toLocaleString(),r:(d.students||[]).length,c,u,j,er});log('Admission import: '+c+' new, '+u+' updated, '+j+' rejected');save();rImp()});
