$(document).on('click','#ap',()=>{const c=S.colleges.find(x=>x.id==$('#cs').val()),code=$('#pc').val().trim().toUpperCase(),nm=$('#pn').val().trim(),er=[];if(!c)er.push('Add a college first.');if(!/^[A-Z0-9]+$/.test(code))er.push('Program code must be letters and numbers only, e.g. BSCS.');if(!nm)er.push('Program name is required.');if(S.colleges.some(k=>k.progs.some(p=>p.code==code)))er.push('That program code already exists.');if(er.length){$('#ce').html(errs(er));return}c.progs.push({code,name:nm});log('Added program '+code+' to '+c.name);save();rCol()});
