$(document).on('click','#dsend',()=>{fresh();const s=stu(B.id),R=s.req||[],off=R.filter(c=>offeredNow(c)&&!preGap(s,c).length),later=R.filter(c=>!off.includes(c)),er=vItems(s,s.draft,true),miss=off.filter(c=>!s.draft.some(i=>{const a=S.sched.find(x=>x.id==i);return a&&a.code==c}));
if(R.length&&!off.length&&!R.some(c=>preGap(s,c).length))er.unshift('None of the requested subjects is offered in the '+ordN(S.sem)+' semester. Use "Student waits for the next opening".');else if(miss.length)er.unshift('Place '+miss.join(', ')+' on the student timetable before approving. Every requested subject offered this semester needs a class.');
if(er.length){$('#de').html(errs(er));return}const rm=$('#rm').val().trim();s.items=s.draft.slice();const aw=affected(s);if(aw.length)s.wait=[...new Set([...(s.wait||[]),...aw])];if(later.length||aw.length){const nw=[...new Set([...later,...aw])];s.wait=[...new Set([...(s.wait||[]),...later])];note(s,'Not enrolled this semester, so you wait: '+nw.map(c=>c+' ('+waitWhy(s,c)+')').join('; ')+'.')}if(R.length)s.req=off;s.draft=null;s.st='Proposal sent';s.stage='dh';note(s,'The Department Head scheduled your subjects. Please review and accept.'+(rm?' Remarks: '+rm:''));log('Department Head sent a schedule to '+s.name);save();shell()});
