$(document).on('click','#sgs',()=>{fresh();const ids=$('.sgk:checked').map(function(){return this.value}).get();if(!ids.length){alert('Select at least one student.');return}const r={ok:0,bad:0,why:new Set(),none:false};ids.forEach(id=>{const s=stu(id);if(!s||!['Awaiting registrar','Revision requested'].includes(s.st))return;const er=vItems(s,s.items,s.stage=='dh');if(er.length){r.bad++;er.forEach(x=>r.why.add(s.name+': '+x))}else{s.st='Proposal sent';s.stage='reg';note(s,'Registrar sent your enrollment proposal. Please review.');r.ok++}});sendMsg([r]);rSpec()});
$(document).on('click','#tsv',()=>{if(sc.sem!=S.sem){alert('Semester '+sc.sem+' is view only.');return}const a=$('#td1').val(),b=$('#td2').val(),m=sc.sem,o=S.terms[m==1?2:1]||{};if(!a||!b){alert('Enter both a start date and an end date.');return}const old=S.terms[m]||{},td=todayISO();if(a!=old.s&&a<td){alert('The start date cannot be in the past.');return}if(b!=old.e&&b<td){alert('The end date cannot be in the past.');return}if(b<=a){alert('The end date must be after the start date.');return}if(m==1&&o.s&&b>=o.s){alert('Semester 1 must end before semester 2 starts.');return}if(m==2&&o.e&&a<=o.e){alert('Semester 2 must start after semester 1 ends.');return}S.terms[m]={s:a,e:b};log('Set semester '+m+' dates '+a+' to '+b);save();rSch()});
$(document).on('click','#rre',()=>{fresh();const s=stu(user.sid);if(sameTerm(s)){alert('You already have a COR for this semester. Request re-enrollment when the next semester opens.');return}requestAligned(s,backOf(s),'Re-enrollment request')});
// Promotion: year level +1, admission number stays the same, student gets a new section and a fresh enrollment cycle.
let pm=[];
// A student can only be promoted when every subject of the current year level has a grade (or is credited).
const ungraded=s=>S.subjects.filter(x=>x.on&&x.yl==s.yl&&subOk(x,s.prog)&&!(s.gr&&s.gr[x.code])&&s.rec[x.code]!='CREDITED'&&!(s.wait||[]).includes(x.code)&&!preGap(s,x.code).length).map(x=>x.code);
function promote(s){if(s.yl>=4)return false;const miss=ungraded(s);if(miss.length){pm.push(s.name+' ('+s.id+') has no grade yet for '+miss.join(', ')+'.');return false}const old=s.yl;s.yl++;s.sec='';s.st='New';s.stage='';s.items=[];s.draft=null;s.req=[];note(s,'The Registrar promoted you from year '+old+' to year '+s.yl+'. Admission no. '+s.adm+' stays the same.');log('Promoted '+s.name+' ('+s.adm+') to year '+s.yl);return true}
$(document).on('click','.pro',function(){fresh();const s=stu($(this).data('id'));pm=[];if(!s)return;if(!promote(s)){bmsg=errs(['Cannot promote yet. '+(pm[0]||''),'Professors must submit all grades first.']);rStu();return}save();rStu()});
$(document).on('click','#spro',()=>{fresh();const L=S.students.filter(s=>s.sec==sv.v);if(!L.length)return;if(!confirm('Promote all '+L.length+' students of '+sv.v+' to the next year level?'))return;pm=[];const n=L.filter(s=>promote(s)).length;bmsg=(n?`<div class="okm">${n} student(s) promoted. They were placed in new sections automatically.</div>`:'')+errs(pm.length?['Not promoted, grades missing:',...pm.slice(0,8),...(pm.length>8?['and '+(pm.length-8)+' more.']:[])]:[]);sv.v='all';save();rStu()});
