$(document).on('click','#fin',()=>{fresh();if(!sv.finc){sv.finc=1;rDash();return}sv.finc=0;const m=S.sem,end=m==2;
S.students.forEach(s=>{if(['Finalized','Proposal sent','Accepted','Awaiting registrar'].includes(s.st)||(s.st=='Revision requested'&&s.cls=='Regular')){s.st='New';s.stage='';s.items=[];s.draft=null;note(s,(end?'The academic year ended. ':'The semester ended. ')+'Waiting for your new proposal.')}});
if(end)S.sched=[];
if(end){S.ay=(S.ay||2026)+1;S.sem=1;S.terms={1:{s:'',e:''},2:{s:'',e:''}};S.yfin={};S.done=[]}else{S.sem=2;S.done=[...(S.done||[]),m]}
S.sections.forEach(x=>syncSec(x.id));releaseWait();log('Finished semester '+m+(end?' and the academic year':'')+'. Now AY '+(S.ay||2026)+', semester '+S.sem);save();
bmsg=`<div class="okm">${end?'Academic year finished.':'1st semester finished.'} Now AY ${S.ay||2026}-${(S.ay||2026)+1}, semester ${S.sem}. Next: ${end?'set the new semester dates in the Scheduler, promote students whose grades are complete (Students tab), ':''}build the schedule, finalize it, then send proposals.</div>`;rDash()});
$(document).on('click','.asm',function(){fresh();if((S.done||[]).includes(+$(this).data('m'))){alert('That semester is finished and cannot be reopened.');return}S.sem=+$(this).data('m');S.students.forEach(s=>{const l=lastCOR(s);if(s.st=='Finalized'&&l&&(l.sem||1)!=S.sem){s.st='New';s.stage='';s.items=[];s.draft=null;note(s,'A new semester opened. Waiting for your new proposal.')}});S.sections.forEach(x=>syncSec(x.id));releaseWait();log('Active semester set to '+S.sem);save();rDash()});
