$(document).on('click','#gsub',()=>{fresh();const[sc3,code]=gc.split('|');let n=0;$('.gsel').each(function(){const v=this.value;if(!v)return;const s=stu($(this).data('id'));s.gr=s.gr||{};if(s.gr[code]&&s.gr[code].g==v)return;s.gr[code]={g:v,by:user.pid,at:new Date().toLocaleDateString()};const st=v=='INC'?'INCOMPLETE':(+v<=3?'PASSED':'FAILED');s.rec[code]=st;n++;note(s,'Grade posted for '+code+': '+v+(st=='FAILED'?'. You failed this subject.':st=='INCOMPLETE'?'. This subject is incomplete.':'.'));if(st!='PASSED'&&s.cls=='Regular'){s.cls='Irregular';note(s,'You now have a back subject, so you are classified as irregular.')}});
log('Submitted '+n+' grades for '+code+' '+sc3);save();bmsg=`<div class="okm">${n} grade(s) submitted to students.</div>`;rSubmit()});
